terraform {
  required_version = ">= 1.6.0"
  required_providers {
    google = {
      source  = "hashicorp/google"
      version = "~> 5.19.0"
    }
  }
}

provider "google" {
  project = var.project_id
  region  = var.region
}

variable "project_id" {
  type        = string
  description = "The GCP Project ID where resources will be deployed."
}

variable "region" {
  type        = string
  description = "The GCP region to deploy resources in."
  default     = "us-central1"
}

variable "image_tag" {
  type        = string
  description = "The Docker image tag to deploy."
  default     = "latest"
}

# Enable required APIs
resource "google_project_service" "apis" {
  for_each = toset([
    "run.googleapis.com",
    "artifactregistry.googleapis.com"
  ])
  service                    = each.key
  disable_on_destroy         = false
}

# Artifact Registry Repository
resource "google_artifact_registry_repository" "repo" {
  depends_on    = [google_project_service.apis]
  location      = var.region
  repository_id = "helloworld-repo"
  description   = "Docker repository for Hello World application"
  format        = "DOCKER"
}

# Dedicated Service Account for Cloud Run
resource "google_service_account" "run_sa" {
  account_id   = "helloworld-run-sa"
  display_name = "Cloud Run Hello World Service Account"
}

# Grant logging.logWriter to the Service Account
resource "google_project_iam_member" "logging_writer" {
  project = var.project_id
  role    = "roles/logging.logWriter"
  member  = "serviceAccount:${google_service_account.run_sa.email}"
}

# Cloud Run Service
resource "google_cloud_run_v2_service" "hello_service" {
  name     = "helloworld-service"
  location = var.region
  ingress  = "INGRESS_TRAFFIC_ALL"

  template {
    service_account = google_service_account.run_sa.email
    containers {
      image = "${var.region}-docker.pkg.dev/${var.project_id}/${google_artifact_registry_repository.repo.repository_id}/helloworld:${var.image_tag}"
      ports {
        container_port = 8080
      }
    }
  }

  depends_on = [
    google_project_service.apis,
    google_artifact_registry_repository.repo
  ]
}

# Allow unauthenticated public access
resource "google_cloud_run_v2_service_iam_member" "public_access" {
  name     = google_cloud_run_v2_service.hello_service.name
  location = google_cloud_run_v2_service.hello_service.location
  role     = "roles/run.invoker"
  member   = "allUsers"
}

output "repository_url" {
  value       = "${var.region}-docker.pkg.dev/${var.project_id}/${google_artifact_registry_repository.repo.repository_id}"
  description = "The Artifact Registry repository URL"
}

output "service_url" {
  value       = google_cloud_run_v2_service.hello_service.uri
  description = "The URL of the deployed Cloud Run service"
}

from fastapi import FastAPI, Request
from fastapi.responses import PlainTextResponse, JSONResponse

app = FastAPI()

@app.get("/")
def read_root(request: Request):
    accept = request.headers.get("accept", "")
    if "application/json" in accept:
        return JSONResponse(content={"message": "Hello, World!"})
    return PlainTextResponse("Hello, World!")

