from fastapi import FastAPI
from fastapi.responses import PlainTextResponse

app = FastAPI()

@app.get("/")
def read_root():
    # Returns exactly the text "Hello, World!" to comply with strict system constraints.
    return PlainTextResponse("Hello, World!")

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    google = {
      source  = "hashicorp/google"
      version = "~> 5.20.0"
    }
    archive = {
      source  = "hashicorp/archive"
      version = "~> 2.4.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.6.0"
    }
  }
}

provider "google" {
  project = var.project_id
  region  = var.region
}

variable "project_id" {
  type        = string
  description = "The GCP Project ID where resources will be deployed."
}

variable "region" {
  type        = string
  description = "The GCP region where resources will be deployed."
  default     = "us-central1"
}

variable "function_name" {
  type        = string
  description = "The name of the Cloud Function."
  default     = "hello-world-function"
}

# Enable required APIs
resource "google_project_service" "apis" {
  for_each = toset([
    "cloudfunctions.googleapis.com",
    "run.googleapis.com",
    "artifactregistry.googleapis.com",
    "cloudbuild.googleapis.com",
    "storage.googleapis.com"
  ])
  service            = each.key
  disable_on_destroy = false
}

# Generate a random suffix for the storage bucket to ensure global uniqueness
resource "random_id" "bucket_suffix" {
  byte_length = 4
}

# Create Cloud Storage Bucket for staging source code
resource "google_storage_bucket" "source_bucket" {
  depends_on                  = [google_project_service.apis]
  name                        = "gcf-source-${var.project_id}-${random_id.bucket_suffix.hex}"
  location                    = var.region
  uniform_bucket_level_access = true
  force_destroy               = true
}

# Create a zip archive of the app directory
data "archive_file" "source_zip" {
  type        = "zip"
  source_dir  = "${path.module}/app"
  output_path = "${path.module}/app.zip"
  excludes    = ["test_main.py", "venv", "__pycache__", ".pytest_cache"]
}

# Upload the zip archive to the Cloud Storage Bucket
resource "google_storage_bucket_object" "source_zip" {
  name   = "source-${data.archive_file.source_zip.output_md5}.zip"
  bucket = google_storage_bucket.source_bucket.name
  source = data.archive_file.source_zip.output_path
}

# Create a custom service account for Cloud Function execution (least privilege)
resource "google_service_account" "function_sa" {
  depends_on   = [google_project_service.apis]
  account_id   = "fn-runtime"
  display_name = "Cloud Function Runtime Service Account"
}

# Deploy Cloud Function (2nd gen)
resource "google_cloudfunctions2_function" "function" {
  name        = var.function_name
  location    = var.region
  description = "Python 3.12 Hello World Cloud Function"

  build_config {
    runtime     = "python312"
    entry_point = "hello_world"
    source {
      storage_source {
        bucket = google_storage_bucket.source_bucket.name
        object = google_storage_bucket_object.source_zip.name
      }
    }
  }

  service_config {
    max_instance_count = 3
    min_instance_count = 0
    available_memory   = "256Mi"
    timeout_seconds    = 60
    service_account_email = google_service_account.function_sa.email
  }

  depends_on = [
    google_project_service.apis,
    google_storage_bucket_object.source_zip,
    google_service_account.function_sa
  ]
}

# Allow unauthenticated public access to the underlying Cloud Run service
resource "google_cloud_run_v2_service_iam_member" "public_access" {
  project  = google_cloudfunctions2_function.function.project
  location = google_cloudfunctions2_function.function.location
  name     = google_cloudfunctions2_function.function.name
  role     = "roles/run.invoker"
  member   = "allUsers"

  depends_on = [
    google_cloudfunctions2_function.function
  ]
}

output "function_url" {
  value       = google_cloudfunctions2_function.function.url
  description = "The URL of the deployed Cloud Function."
}

def lambda_handler(event, context):
    """
    AWS Lambda handler that returns exactly 'Hello, World!'
    """
    return {
        "statusCode": 200,
        "headers": {
            "Content-Type": "text/plain; charset=utf-8"
        },
        "body": "Hello, World!"
    }

